# Let's match the songs in old_songs to the song_id in song_id_to_details by comparing both title and all artists.
# We'll build a set of song_ids that correspond to the old songs.

def normalize(s):
    return s.strip().lower()

old_song_ids = set()
for song_id, details in song_id_to_details.items():
    song_title = normalize(details["title"])
    song_artists = set(normalize(artist["name"]) for artist in details["artists"])
    for old_song in old_songs:
        if song_title == normalize(old_song["title"]):
            old_artists = set(normalize(a) for a in old_song["artists"])
            if old_artists.issubset(song_artists):
                old_song_ids.add(int(song_id))

print(old_song_ids)  # These are the song_ids to remove from playlists and add to the new playlist.

